result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/checkmate/checkmate/engine.py", "content": """"Checkmate engine: declarative, rules-file-driven validation for CSV files.

Rules live in a JSON file with two kinds of entries:

  * ``row_count_min`` (optional, dataset-level): minimum number of data rows.
  * ``columns``: mapping of column name -> spec dict. A spec may contain any of:
      not_null        (true)              value must be present / non-blank
      unique          (true)              no duplicate non-blank values
      type            "int"|"float"|"date" value must parse as that type
                                          (dates use strict ISO YYYY-MM-DD)
      min             number              numeric value >= min
      max             number              numeric value <= min
      regex           string              value matches pattern (re.search)
      allowed_values  list                value is one of the listed values
    plus an optional per-column ``severity`` ("ERROR", default, or "WARN").

Only ERROR-level failures make a run fail; WARN failures are reported but do
not affect the overall pass/fail status or CLI exit code.

Row numbers are 1-based indices over the *data* rows (the header is row 0).
Blank values are only flagged by ``not_null``; all other rules skip blanks.
"""

from __future__ import annotations

import csv
import json
import re
from datetime import datetime
from pathlib import Path

KNOWN_RULES = {"not_null", "unique", "type", "min", "max", "regex", "allowed_values"}
KNOWN_TYPES = {"int", "float", "date"}
SEVERITIES = {"ERROR", "WARN"}
FAILING_ROWS_CAP = 20

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")
_INT_RE = re.compile(r"[+-]?\d+")


class CheckmateError(Exception):
    """Base class for all checkmate errors."""


class UnknownRuleError(CheckmateError):
    """Raised when rules.json names a rule checkmate does not know."""


class SchemaError(CheckmateError):
    """Raised when rules.json is structurally invalid."""


def _parse_int(text):
    text = text.strip()
    return int(text) if _INT_RE.fullmatch(text) else None


def _parse_float(text):
    try:
        return float(text.strip())
    except ValueError:
        return None


def _parse_date(text):
    text = text.strip()
    if not _DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.strptime(text, "%Y-%m-%d")
    except ValueError:  # e.g. 2020-02-30: right shape, impossible date
        return None


_TYPE_PARSERS = {"int": _parse_int, "float": _parse_float, "date": _parse_date}


def load_rules(rules_path):
    """Load and validate a rules file. Raises UnknownRuleError/SchemaError."""
    path = Path(rules_path)
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise SchemaError(f"rules file not found: {path}") from exc
    except json.JSONDecodeError as exc:
        raise SchemaError(f"rules file is not valid JSON: {path}: {exc}") from exc

    if not isinstance(raw, dict):
        raise SchemaError("rules file must be a JSON object")

    row_count_min = raw.get("row_count_min")
    if row_count_min is not None and (
        not isinstance(row_count_min, int) or isinstance(row_count_min, bool) or row_count_min < 0
    ):
        raise SchemaError("'row_count_min' must be a non-negative integer")

    columns = raw.get("columns", {})
    if not isinstance(columns, dict):
        raise SchemaError("'columns' must be an object mapping column name -> rules")

    for column, spec in columns.items():
        if not isinstance(spec, dict):
            raise SchemaError(f"rules for column '{column}' must be an object")
        for rule in spec:
            if rule == "severity":
                continue
            if rule not in KNOWN_RULES:
                raise UnknownRuleError(
                    f"unknown rule '{rule}' for column '{column}'. "
                    f"Known rules: {sorted(KNOWN_RULES)}"
                )
        severity = spec.get("severity", "ERROR")
        if severity not in SEVERITIES:
            raise UnknownRuleError(
                f"unknown severity '{severity}' for column '{column}'. "
                f"Known severities: {sorted(SEVERITIES)}"
            )
        declared_type = spec.get("type")
        if declared_type is not None and declared_type not in KNOWN_TYPES:
            raise UnknownRuleError(
                f"unknown type '{declared_type}' for column '{column}' "
                f"(expected one of {sorted(KNOWN_TYPES)})"
            )
        if "regex" in spec:
            try:
                re.compile(spec["regex"])
            except re.error as exc:
                raise SchemaError(
                    f"invalid regex for column '{column}': {spec['regex']!r} ({exc})"
                ) from exc

    return {
        "row_count_min": row_count_min,
        "columns": columns,
    }


def _evaluate_column(rows, column, spec):
    """Return {rule_name: [failing 1-based data row numbers]} for one column."""
    violations = {rule: [] for rule in spec if rule != "severity"}
    seen = {}

    for row_no, row in enumerate(rows, start=1):
        raw = row.get(column)
        value = "" if raw is None else str(raw)
        stripped = value.strip()

        if "not_null" in violations and stripped == "":
            violations["not_null"].append(row_no)

        # All other rules skip blank values.
        if stripped == "":
            continue

        if "unique" in violations:
            if stripped in seen:
                violations["unique"].append(row_no)
            else:
                seen[stripped] = row_no

        parsed = None
        if "type" in violations:
            parsed = _TYPE_PARSERS[spec["type"]](stripped)
            if parsed is None:
                violations["type"].append(row_no)

        if "min" in violations or "max" in violations:
            number = parsed if isinstance(parsed, (int, float)) else _parse_float(stripped)
            if number is not None:  # unparseable values are the 'type' rule's job
                if "min" in violations and number < spec["min"]:
                    violations["min"].append(row_no)
                if "max" in violations and number > spec["max"]:
                    violations["max"].append(row_no)

        if "regex" in violations and re.search(spec["regex"], value) is None:
            violations["regex"].append(row_no)

        if "allowed_values" in violations and value not in spec["allowed_values"]:
            violations["allowed_values"].append(row_no)

    return violations


def validate(csv_path, rules_path):
    """Validate a CSV against a rules file.

    Returns a result dict:

        {
          "file": str, "rules_file": str, "row_count": int,
          "checks": [
            {
              "column": str | None,       # None for dataset-level checks
              "rule": str,
              "severity": "ERROR" | "WARN",
              "passed": bool,
              "violation_count": int,     # total failing rows (uncapped)
              "failing_rows": [int, ...], # first <=20 failing data rows (1-based)
              "rows_capped": bool,
            }, ...
          ],
          "checks_passed": int,
          "checks_failed": int,           # total failed checks
          "failed_error_checks": [...],   # subset of checks with severity ERROR
          "failed_warn_checks": [...],    # subset of checks with severity WARN
          "passed": bool,                 # True iff no ERROR-level check failed
        }
    """
    csv_path = Path(csv_path)
    rules = load_rules(rules_path)

    try:
        with open(csv_path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            fieldnames = reader.fieldnames or []
            rows = list(reader)
    except FileNotFoundError as exc:
        raise CheckmateError(f"CSV file not found: {csv_path}") from exc

    unknown_columns = set(rules["columns"]) - set(fieldnames)
    if unknown_columns:
        raise SchemaError(
            f"rules reference column(s) missing from CSV header: "
            f"{sorted(unknown_columns)}; header is {fieldnames}"
        )

    def make_check(column, rule, severity, failing_rows):
        return {
            "column": column,
            "rule": rule,
            "severity": severity,
            "passed": not failing_rows,
            "violation_count": len(failing_rows),
            "failing_rows": failing_rows[:FAILING_ROWS_CAP],
            "rows_capped": len(failing_rows) > FAILING_ROWS_CAP,
        }

    checks = []
    if rules["row_count_min"] is not None:
        failing = [] if len(rows) >= rules["row_count_min"] else [len(rows)]
        checks.append(make_check(None, "row_count_min", "ERROR", failing))

    for column, spec in rules["columns"].items():
        severity = spec.get("severity", "ERROR")
        violations = _evaluate_column(rows, column, spec)
        for rule in spec:
            if rule == "severity":
                continue
            checks.append(make_check(column, rule, severity, violations[rule]))

    failed_error = [c for c in checks if not c["passed"] and c["severity"] == "ERROR"]
    failed_warn = [c for c in checks if not c["passed"] and c["severity"] == "WARN"]

    return {
        "file": str(csv_path),
        "rules_file": str(rules_path),
        "row_count": len(rows),
        "checks": checks,
        "checks_passed": sum(1 for c in checks if c["passed"]),
        "checks_failed": sum(1 for c in checks if not c["passed"]),
        "failed_error_checks": failed_error,
        "failed_warn_checks": failed_warn,
        "passed": not failed_error,
    }
"})
